#!/usr/bin/env python3
"""Unified regression entrypoint for Quality-Disposition-Dashboard.

The six regression suites are embedded here so the repository has one
regression command. Each suite is executed in a short-lived child process to
preserve its original isolation, environment and temporary-database behavior.
No production database is used by these suites.

Usage:
    python3 regression.py             # run all six embedded regression suites
    python3 regression.py --list      # list suites
    python3 regression.py --suite ... # run one suite by name
"""
from __future__ import annotations

import argparse
import os
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent

REGRESSION_SMOKE_SOURCE = 'import os, sys, tempfile, threading, json, gzip, shutil\nfrom pathlib import Path\nfrom datetime import date\n\nROOT = Path(__file__).resolve().parent\nif not (ROOT / \'server.py\').exists():   # works from the repo root or from a tests/ subfolder\n    ROOT = ROOT.parent\nwith tempfile.TemporaryDirectory(prefix=\'qdash_v61_\') as td:\n    db = Path(td)/\'quality.db\'\n    backups = Path(td)/\'backups\'\n    os.environ[\'DB_PATH\'] = str(db)\n    os.environ[\'APP_VERSION\'] = \'test\'\n    os.environ[\'BACKUP_DIR\'] = str(backups)\n    os.environ.pop(\'RENDER\', None)\n    sys.path.insert(0, str(ROOT))\n    import server\n\n    # fresh schema\n    server._ensure_admin_schema()\n    server.ensure_fast_indexes()\n    server.STARTUP_READY = True\n    server.STARTUP_ERROR = \'\'\n\n    # Validate date derivation / fixture contract\n    rows = []\n    for i, d in enumerate([date(2026,9,1), date(2026,9,2), date(2026,8,28)], start=1):\n        m,w,q,fy = server._derive_period_fields(d)\n        rows.append({\n            \'heat_no\': f\'H{i}\', \'batch_no\': f\'B{i}\', \'work_center\': \'WC1\', \'grade\': \'A\',\n            \'output_weight\': 10.0+i, \'main_defect\': \'ROLL MARK\' if i < 3 else \'\',\n            \'defect_intensity\': \'LIGHT\' if i == 1 else \'\',\n            \'quality_decision\': \'PRIME\' if i < 3 else \'REJECT\',\n            \'insp_lot_date\': d.isoformat(), \'ud_date\': \'\', \'month\': m, \'week\': w,\n            \'quarter\': q, \'financial_year\': fy,\n        })\n\n    # Basic insert and idempotent re-import\n    r1 = server._insert_records(rows)\n    assert r1[\'inserted\'] == 3 and r1[\'updated\'] == 0\n    r2 = server._insert_records(rows)\n    assert r2[\'inserted\'] == 0 and r2[\'updated\'] == 0 and r2[\'duplicates\'] == 3\n\n    # Update-by-batch behavior\n    changed = dict(rows[0]); changed[\'quality_decision\'] = \'RE-WORK\'; changed[\'output_weight\'] = 99.0\n    r3 = server._insert_records([changed])\n    assert r3[\'updated\'] == 1 and r3[\'inserted\'] == 0\n\n    # Concurrent imports for the same new batch: exactly one insert\n    d = date(2026,9,3); m,w,q,fy = server._derive_period_fields(d)\n    race = dict(rows[0]); race.update({\'heat_no\':\'HRACE\',\'batch_no\':\'BRACE\',\'output_weight\':22.0,\'quality_decision\':\'PRIME\',\'insp_lot_date\':d.isoformat(),\'month\':m,\'week\':w,\'quarter\':q,\'financial_year\':fy})\n    results=[]; errors=[]\n    def worker():\n        try: results.append(server._insert_records([race]))\n        except Exception as e: errors.append(e)\n    ts=[threading.Thread(target=worker) for _ in range(6)]\n    [t.start() for t in ts]; [t.join() for t in ts]\n    assert not errors, errors\n    conn=server.get_conn(); count=conn.execute(\'SELECT COUNT(*) FROM disposition WHERE batch_no=?\',(\'BRACE\',)).fetchone()[0]; conn.close()\n    assert count == 1, count\n\n    # KPI/analysis smoke\n    filt = {k:\'All\' for k in server.FILTER_KEYS}\n    kpi = server.compute_kpis(filt)\n    assert len(kpi[\'kpis\']) == 12\n    assert kpi[\'totals\'][\'total_coils\'] >= 4\n    assert server.compute_monthly_trend(filt)[\'rows\']\n    assert server.compute_period_trend(filt)[\'rows\']\n    assert server.compute_defect_analysis(filt)[\'register\']\n    wcg = server.compute_work_center_grade(filt)\n    assert isinstance(wcg, dict) and wcg, wcg\n    server.compute_qcr_intelligence(filt, server.compute_monthly_trend(filt), server.compute_defect_analysis(filt), wcg, kpi)\n\n    # Cache invariants\n    server._cache_clear()\n    for i in range(150):\n        server._cache_put((f\'k{i}\',), {\'payload\':\'x\'*1000})\n    assert len(server.RESPONSE_CACHE) <= server.RESPONSE_CACHE_MAX_ENTRIES\n    assert server.RESPONSE_CACHE_BYTES <= server.RESPONSE_CACHE_MAX_BYTES\n    server._cache_clear(); assert server.RESPONSE_CACHE_BYTES == 0\n\n    # Activity retention\n    conn=server.get_conn()\n    for i in range(10050):\n        conn.execute(\'INSERT INTO activity_log (event_type,ip_address,visitor_id) VALUES (?,?,?)\', (\'dashboard_open\', \'127.0.0.1\', str(i)))\n    conn.commit(); conn.close()\n    server._cleanup_activity_log(server.get_conn(), keep=10000)\n    conn=server.get_conn(); ac=conn.execute(\'SELECT COUNT(*) FROM activity_log\').fetchone()[0]; conn.close()\n    assert ac <= 10000, ac\n\n    # Backup create + integrity + tamper detection + restore\n    server.BACKUP_DIR = str(backups); backups.mkdir(parents=True, exist_ok=True)\n    out = server._write_backup_file(\'regression\')\n    assert out and out[\'filename\']\n    fpath = backups / out[\'filename\']\n    with gzip.open(fpath, \'rt\', encoding=\'utf-8\') as fh: payload=json.load(fh)\n    ok, msg = server._backup_is_valid(payload)\n    assert ok and \'verified\' in msg.lower(), msg\n    tampered=dict(payload); tampered[\'counts\']=dict(tampered[\'counts\']); tampered[\'counts\'][\'disposition\'] += 1\n    ok, msg=server._backup_is_valid(tampered)\n    assert not ok and \'mismatch\' in msg.lower(), msg\n\n    # Legacy backup compatibility remains available without weakening V4\n    # validation for new full-state backups.\n    legacy = dict(payload)\n    legacy.pop(\'integrity_sha256\', None)\n    legacy[\'backup_version\'] = 3\n    legacy.pop(\'scope\', None)\n    for key in (\'users\',\'activity_log\',\'audit_trail\',\'fishbone_import_history\'):\n        legacy.pop(key, None)\n    ok, msg = server._backup_is_valid(legacy)\n    assert ok and \'legacy\' in msg.lower(), msg\n\n    # Safety-backup failure must block a mutation rather than silently continue.\n    original_writer = server._write_backup_file\n    try:\n        server._write_backup_file = lambda reason: None\n        blocked = False\n        try:\n            server._require_safety_backup(\'regression_block\')\n        except RuntimeError:\n            blocked = True\n        assert blocked\n    finally:\n        server._write_backup_file = original_writer\n\n    # Restore failures must roll back the entire transaction.\n    conn=server.get_conn()\n    before_count=conn.execute("SELECT COUNT(*) FROM disposition").fetchone()[0]\n    conn.close()\n    bad_restore = dict(payload)\n    bad_restore[\'disposition\'] = list(payload[\'disposition\'])\n    bad_restore[\'disposition\'].append(dict(payload[\'disposition\'][0]))\n    try:\n        server._restore_backup_data(bad_restore)\n        raise AssertionError(\'malformed restore unexpectedly succeeded\')\n    except ValueError:\n        pass\n    conn=server.get_conn()\n    after_count=conn.execute("SELECT COUNT(*) FROM disposition").fetchone()[0]\n    conn.close()\n    assert after_count == before_count, (before_count, after_count)\n\n    # Restore into changed DB snapshot, then verify rollback-safe path logic\n    conn=server.get_conn(); conn.execute("DELETE FROM disposition WHERE batch_no=\'BRACE\'"); conn.commit(); conn.close()\n    counts=server._restore_backup_data(payload)\n    assert counts[\'disposition\'] >= 4\n    assert counts[\'users\'] is not None and counts[\'activity_log\'] is not None\n    assert counts[\'audit_trail\'] is not None and counts[\'fishbone_import_history\'] is not None\n    assert payload.get(\'scope\') == \'full_persistent_application_state\'\n    assert all(k in payload for k in (\'users\',\'activity_log\',\'audit_trail\',\'fishbone_import_history\'))\n\n    # Backup structural validation catches tampered row/count metadata even\n    # when a legacy payload has no checksum.\n    legacy = dict(payload)\n    legacy.pop(\'integrity_sha256\', None)\n    legacy[\'counts\'] = dict(legacy[\'counts\'])\n    legacy[\'counts\'][\'users\'] += 1\n    ok, msg = server._backup_is_valid(legacy)\n    assert not ok and \'count mismatch\' in msg.lower(), msg\n\n    # Input validation / CSV injection\n    bad=dict(rows[0]); bad[\'batch_no\']=\'BAD\'; bad[\'output_weight\']=float(\'nan\')\n    assert server._validate_record(bad) == \'Output Weight must be a finite number\'\n    assert server._csv_safe_value(\'=SUM(A1)\') == "\'=SUM(A1)"\n    assert server._csv_safe_value(12.5) == 12.5\n\n    # Report filenames must never inject HTTP header control characters or\n    # quoted path separators into Content-Disposition.\n    from reports import _safe_filename\n    fn = _safe_filename({\'Defect\': \'A\\\\r\\\\nContent-Disposition: x\', \'Grade\': \'A/B"Q\'}, \'.xlsx\')\n    assert \'\\\\r\' not in fn and \'\\\\n\' not in fn and \'"\' not in fn and \'\\\\\\\\\' not in fn\n    assert \'/\' not in fn and fn.endswith(\'.xlsx\')\n\n    # HTTP health/readiness smoke using an in-process server\n    from http.server import ThreadingHTTPServer\n    import urllib.request, urllib.error\n    httpd = ThreadingHTTPServer((\'127.0.0.1\',0), server.Handler)\n    port=httpd.server_address[1]\n    th=threading.Thread(target=httpd.serve_forever, daemon=True); th.start()\n    try:\n        for path in [\'/healthz\',\'/readyz\',\'/api/auth/status\',\'/api/filters\',\'/api/kpis\']:\n            with urllib.request.urlopen(f\'http://127.0.0.1:{port}{path}\', timeout=5) as resp:\n                assert resp.status == 200, (path, resp.status)\n                data=resp.read()\n                assert data, path\n\n        # Render ADMIN_PASSWORD is provisioning-only: once a DB user exists,\n        # the old environment password must not continue to authenticate.\n        server.ADMIN_USERNAME = \'render_admin\'\n        server.ADMIN_PASSWORD = \'EnvOnly-Strong-Password-1!\'\n        def post_json(path, body):\n            req = urllib.request.Request(\n                f\'http://127.0.0.1:{port}{path}\',\n                data=json.dumps(body).encode(),\n                headers={\'Content-Type\':\'application/json\'},\n                method=\'POST\'\n            )\n            try:\n                with urllib.request.urlopen(req, timeout=5) as resp:\n                    return resp.status, json.loads(resp.read().decode())\n            except urllib.error.HTTPError as e:\n                return e.code, json.loads(e.read().decode())\n        status, body = post_json(\'/api/login\', {\'username\':\'render_admin\',\'password\':server.ADMIN_PASSWORD})\n        assert status == 200 and body.get(\'authenticated\') is True, (status, body)\n        conn=server.get_conn()\n        conn.execute("DELETE FROM users WHERE username=?", (\'render_admin\',))\n        conn.execute("INSERT INTO users (username,display_name,password_hash,role,active,must_reset_password) VALUES (?,?,?,?,?,?)",\n                     (\'render_admin\',\'Render Admin\',server._hash_password(\'DatabaseOnly-Strong-Password-2!\'),\'admin\',1,0))\n        conn.commit(); conn.close()\n        status, _ = post_json(\'/api/login\', {\'username\':\'render_admin\',\'password\':\'EnvOnly-Strong-Password-1!\'})\n        assert status == 401, status\n        status, body = post_json(\'/api/login\', {\'username\':\'render_admin\',\'password\':\'DatabaseOnly-Strong-Password-2!\'})\n        assert status == 200 and body.get(\'authenticated\') is True, (status, body)\n    finally:\n        httpd.shutdown(); httpd.server_close(); th.join(timeout=2)\n\n    # Admin inline-handler hardening: dynamic strings must not be injected into\n    # double-quoted HTML attributes through raw JSON.stringify()/HTML escaping.\n    admin_html = (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\n    assert \'function escAttrJs(value)\' in admin_html\n    assert \'revokeAdminSession(${JSON.stringify(s.username)})\' not in admin_html\n    assert "fbSaveAlias(\'${esc(r.defect)" not in admin_html\n    assert \'loadRecords(${JSON.stringify(String(r.id))})\' not in admin_html\n    assert "resetUserPassword(${r.id},\'${escAttrJs(r.username)}\')" in admin_html\n\n    # Security hardening invariants.\n    src = (ROOT / \'server.py\').read_text(encoding=\'utf-8\')\n    assert \'not row\' in src[src.find(\'if path == "/api/login":\'):src.find(\'if path == "/api/logout":\')]\n    assert \'before_disposition_import\' in src\n    assert \'before_record_delete\' in src\n    assert \'before_fishbone_alias_set\' in src\n    assert \'before_fishbone_alias_delete\' in src\n    assert \'TRUST_PROXY_HEADERS", "false"\' in src\n    assert \'scope": "full_persistent_application_state"\' in src\n    assert \'backup_version\' in src and \'version >= 4\' in src\n\n    print(\'DEEP REGRESSION PASS\')\n    print(\'rows_ok=1 import_concurrency=1 kpi=1 cache=1 activity_retention=1 backup_integrity=1 restore=1 restore_rollback=1 full_state_backup=1 safety_gate=1 report_filename=1 http=1 admin_handler_hardening=1 security_hardening=1\')\n'

REGRESSION_TEST_SOURCE = '"""Non-destructive HTTP regression suite.\nStarts the local app against an isolated, disposable copy of the bundled\nSQLite DB (never the real persistent store) and verifies core contracts.\n"""\nimport json, os, shutil, sqlite3, subprocess, sys, tempfile, time, urllib.parse, urllib.request\nfrom pathlib import Path\n\nROOT=Path(__file__).resolve().parent\nPORT=8765\nBASE=f"http://127.0.0.1:{PORT}"\n\ndef get(path):\n    req=urllib.request.Request(BASE+path, headers={"Accept":"application/json"})\n    with urllib.request.urlopen(req, timeout=8) as r:\n        return r.status, json.loads(r.read().decode("utf-8")), dict(r.headers)\n\ndef post(path, body):\n    data=json.dumps(body).encode()\n    req=urllib.request.Request(BASE+path,data=data,method="POST",headers={"Content-Type":"application/json"})\n    with urllib.request.urlopen(req, timeout=8) as r:\n        return r.status, json.loads(r.read().decode("utf-8"))\n\ndef main():\n    tmpdir = tempfile.mkdtemp(prefix="qcr_regression_")\n    db = os.path.join(tmpdir, "quality.db")\n    shutil.copy2(ROOT/"quality.db", db)\n    try:\n        con=sqlite3.connect(db)\n        before=con.execute("select count(*) from disposition").fetchone()[0]\n        fp=con.execute("select coalesce(sum(output_weight),0), min(id), max(id) from disposition").fetchone()\n        con.close()\n        env=os.environ.copy(); env["PORT"]=str(PORT); env.pop("ADMIN_USERNAME",None); env.pop("ADMIN_PASSWORD",None)\n        env["DB_PATH"]=db  # isolated, disposable — never the real persistent database\n        p=subprocess.Popen([sys.executable,"server.py"],cwd=ROOT,env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)\n        try:\n            for _ in range(40):\n                try: get("/api/health"); break\n                except Exception: time.sleep(.15)\n            else: raise RuntimeError("server did not start")\n            checks=[]\n            for path in ["/api/health","/api/connection_status","/api/filters","/api/kpis","/api/qcr","/api/work_center_grade","/api/defect_analysis","/api/monthly_trend","/api/period_trend","/api/data_freshness"]:\n                status,data,headers=get(path)\n                assert status==200, (path,status)\n                assert "X-Request-ID" in headers, path\n                checks.append(path)\n            # Exercise the real filter contract without changing data.\n            params=urllib.parse.urlencode({"work_center":"CND_4HI"})\n            status,_data,_=get("/api/kpis?"+params); assert status==200\n            status,_data,_=get("/api/qcr?"+params); assert status==200\n            con=sqlite3.connect(db)\n            after=con.execute("select count(*) from disposition").fetchone()[0]\n            fp2=con.execute("select coalesce(sum(output_weight),0), min(id), max(id) from disposition").fetchone()\n            con.close()\n            assert before==after and fp==fp2, (before,after,fp,fp2)\n            print(f"REGRESSION PASS — {before} disposition records unchanged; {len(checks)} core endpoints + filter contract OK.")\n        finally:\n            p.terminate();\n            try: p.wait(timeout=3)\n            except subprocess.TimeoutExpired: p.kill()\n    finally:\n        shutil.rmtree(tmpdir, ignore_errors=True)\n\nmain()\n'

REGRESSION_V64_3_SOURCE = '"""V64.3 regression checks (isolated temp database; never touches production data).\n\nCovers: one-response-per-request, malformed filter values, Data Quality Monitor\nkey alignment, intensity rule for NO DEFECT coils, drill-down totals, per-FY quarters.\n"""\nimport os, sys, re, json, socket, tempfile, threading, http.client\nfrom pathlib import Path\nfrom datetime import date\n\nROOT = Path(__file__).resolve().parent\nwith tempfile.TemporaryDirectory(prefix=\'qdash_v643_\') as td:\n    os.environ.update(DB_PATH=str(Path(td) / \'quality.db\'), APP_VERSION=\'test\',\n                      ADMIN_USERNAME=\'admin\', ADMIN_PASSWORD=\'Strong-Admin-1234!\')\n    os.environ.pop(\'RENDER\', None)\n    sys.path.insert(0, str(ROOT))\n    import server\n    server._ensure_admin_schema(); server.ensure_fast_indexes(); server.STARTUP_READY = True\n    _c = server.get_conn(); _c.execute(\'DELETE FROM disposition\'); _c.commit(); _c.close()   # start from a known, tiny dataset\n\n    def rec(batch, d, defect, intensity, decision=\'PRIME\', w=5.0):\n        m, wk, q, fy = server._derive_period_fields(d)\n        return {\'heat_no\': \'H\' + batch, \'batch_no\': batch, \'work_center\': \'WC1\', \'grade\': \'A\', \'output_weight\': w,\n                \'main_defect\': defect, \'defect_intensity\': intensity, \'quality_decision\': decision,\n                \'insp_lot_date\': d.isoformat(), \'ud_date\': \'\', \'month\': m, \'week\': wk, \'quarter\': q, \'financial_year\': fy}\n    server._insert_records([\n        rec(\'B1\', date(2026, 5, 4), \'NO DEFECT\', \'\'),\n        rec(\'B2\', date(2026, 5, 5), \'STICKING\', \'LIGHT\', \'REJECT\'),\n        rec(\'B3\', date(2026, 5, 6), \'STICKING\', \'\'),            # the ONLY real intensity gap\n        rec(\'B4\', date(2027, 5, 4), \'NO DEFECT\', \'\'),           # same quarter label, next FY\n    ])\n    from http.server import ThreadingHTTPServer\n    httpd = ThreadingHTTPServer((\'127.0.0.1\', 0), server.Handler)\n    port = httpd.server_address[1]\n    threading.Thread(target=httpd.serve_forever, daemon=True).start()\n    errors = []\n\n    def raw(path):\n        s = socket.create_connection((\'127.0.0.1\', port))\n        s.sendall(f\'GET {path} HTTP/1.1\\r\\nHost: x\\r\\nConnection: close\\r\\n\\r\\n\'.encode())\n        data = b\'\'\n        while True:\n            c = s.recv(65536)\n            if not c: break\n            data += c\n        return data\n\n    def get(path, cookie=\'\'):\n        c = http.client.HTTPConnection(\'127.0.0.1\', port, timeout=20)\n        c.request(\'GET\', path, headers={\'Cookie\': cookie} if cookie else {})\n        r = c.getresponse(); b = r.read(); c.close()\n        return r.status, (json.loads(b) if b[:1] in (b\'{\', b\'[\') else b)\n\n    # 1) exactly one HTTP response per request\n    for p in (\'/api/kpis\', \'/api/filters\', \'/api/export/csv\', \'/\', \'/api/nope\'):\n        n = raw(p).count(b\'HTTP/1.\')\n        if n != 1: errors.append(f\'{p}: {n} HTTP responses in one stream\')\n\n    # 2) malformed / odd-case filter values never produce a 500\n    for q in (\'month=garbage\', \'week=garbage\', \'financial_year=junk\', \'month=ALL\', \'quarter=X&financial_year=FY%202026-27\'):\n        for ep in (\'/api/kpis\', \'/api/qcr\', \'/api/period_trend\', \'/api/drilldown?metric=Total%20Coils&\'):\n            url = ep + (\'\' if ep.endswith(\'&\') else \'?\') + q\n            s, d = get(url)\n            if s != 200: errors.append(f\'{url} -> {s}\')\n            if ep == \'/api/qcr\' and isinstance(d, dict) and d.get(\'section_errors\'): errors.append(f\'{url} section_errors {d["section_errors"]}\')\n    s, d = get(\'/api/kpis?month=ALL\')\n    if d[\'totals\'][\'total_coils\'] != 4: errors.append(\'month=ALL should behave like All\')\n    s, d = get(\'/api/drilldown?metric=Total%20Coils&page=abc&page_size=x\')\n    if s != 200 or d.get(\'page\') != 1: errors.append(\'non-numeric page must fall back to defaults\')\n\n    # 3) drill-down count / rows agree, including the NO DEFECT edge case\n    for m, v in ((\'defect_category\', \'NO DEFECT\'), (\'defect_category\', \'STICKING\'), (\'Reject Qty (MT)\', None)):\n        s, d = get(\'/api/drilldown?metric=\' + m.replace(\' \', \'%20\') + ((\'&drill_value=\' + v.replace(\' \', \'%20\')) if v else \'\'))\n        if d[\'row_count\'] != len(d[\'rows\']): errors.append(f\'drill {m}/{v}: row_count {d["row_count"]} != rows {len(d["rows"])}\')\n\n    # 4) quarters are grouped per financial year\n    s, d = get(\'/api/period_trend\')\n    names = [r[\'name\'] for r in d[\'quarterly\']]\n    if names != [\'Q1 (FY 2026-27)\', \'Q1 (FY 2027-28)\']: errors.append(f\'quarterly labels {names}\')\n    if [r[\'coils\'] for r in d[\'quarterly\']] != [3, 1]: errors.append(\'quarterly coil counts wrong\')\n\n    # 5) Data Quality Monitor: UI keys exist in the payload, NO DEFECT coils are not flagged\n    import urllib.request\n    login = urllib.request.Request(f\'http://127.0.0.1:{port}/api/login\', data=json.dumps({\'username\': \'admin\', \'password\': \'Strong-Admin-1234!\'}).encode(), headers={\'Content-Type\': \'application/json\'}, method=\'POST\')\n    with urllib.request.urlopen(login) as r:\n        cookie = \'; \'.join(h.split(\';\')[0] for h in r.headers.get_all(\'Set-Cookie\'))\n    s, dq = get(\'/api/admin/data_quality\', cookie)\n    html = (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\n    fn = re.search(r\'async function loadDataQuality\\(\\)\\{.*?\\n\', html).group(0)\n    for key in set(re.findall(r\'\\bi\\.([a-z_]+)\', fn)):\n        if key not in dq[\'issues\']: errors.append(f\'admin.html loadDataQuality reads unknown key issues.{key}\')\n    if dq[\'issues\'][\'missing_intensity\'] != 1: errors.append(f\'missing_intensity should be 1, got {dq["issues"]["missing_intensity"]}\')\n    if \'records_require_correction\' not in dq or \'dqCorrections\' not in fn: errors.append(\'records_require_correction not wired to the UI\')\n\n    # 6) KPI target validation\n    import urllib.error\n    def post(path, body):\n        req = urllib.request.Request(f\'http://127.0.0.1:{port}{path}\', data=json.dumps(body).encode(), method=\'POST\',\n                                     headers={\'Content-Type\': \'application/json\', \'Cookie\': cookie, \'X-CSRF-Token\': re.search(r\'qdash_csrf=([^;]+)\', cookie).group(1)})\n        try:\n            with urllib.request.urlopen(req) as r: return r.status\n        except urllib.error.HTTPError as e: return e.code\n    if post(\'/api/admin/kpi_target\', {\'label\': \'Defect Rate\', \'target\': \'nan\', \'warning\': 0.03, \'critical\': 0.05, \'direction\': \'lower\'}) != 400: errors.append(\'NaN KPI target accepted\')\n    if post(\'/api/admin/kpi_target\', {\'label\': \'Defect Rate\', \'target\': 0.05, \'warning\': 0.03, \'critical\': 0.01, \'direction\': \'lower\'}) != 400: errors.append(\'reversed KPI bands accepted\')\n\n    # 9) the Defect Intensity Breakdown chart\'s drill-down (added after the\n    #    scroll/fishbone fixes above) must return the same counts the chart\n    #    itself displays, including the "WITHOUT INTENSITY" bucket which maps\n    #    to a blank/NULL column value rather than a literal string match.\n    for level, expect in ((\'LIGHT\', 1), (\'WITHOUT INTENSITY\', 3)):\n        s, d = get(\'/api/drilldown?metric=intensity_category&drill_value=\' + level.replace(\' \', \'%20\'))\n        if s != 200 or d.get(\'count\') != expect:\n            errors.append(f\'intensity_category drilldown for {level!r}: status={s} count={d.get("count")} expected={expect}\')\n\n    # 7) scroll-to-top on tab switch: no server-side check possible headlessly here,\n    #    so assert the browser-facing contract in app.js instead - every activateTab\n    #    call resets scroll unless it explicitly opts out for back/forward navigation.\n    appjs = (ROOT / \'app.js\').read_text(encoding=\'utf-8\')\n    if \'function resetPageScroll(\' not in appjs: errors.append(\'resetPageScroll() helper missing from app.js\')\n    if \'if(!(opts && opts.keepScroll)) resetPageScroll();\' not in appjs: errors.append(\'activateTab no longer resets scroll on switch\')\n\n    # 8) restoring a backup that contains fishbone import history must not 500\n    #    (INSERT column count previously did not match the supplied values).\n    try:\n        import openpyxl\n        wb = __import__(\'io\').BytesIO()\n        book = openpyxl.Workbook(); ws = book.active\n        ws.append(["Defect Name", "Man", "Machine", "Material", "Method", "Measurement", "Environment"])\n        ws.append(["STICKING", "Operator error", "Roll wear", "Batch impurity", "SOP gap", "Gauge drift", "Humidity"])\n        book.save(wb); wb.seek(0)\n        bundle = server._parse_fishbone_file(\'fb.xlsx\', wb.read())\n        server._replace_fishbone_master(bundle, \'fb.xlsx\', \'admin\')\n    except ImportError:\n        pass  # openpyxl not installed in this environment; the restore check below still runs against whatever history exists\n    snap = server._backup_snapshot_transaction(\'test\')\n    try:\n        server._restore_backup_data(snap)\n    except Exception as e:\n        errors.append(f\'restoring a backup with fishbone_import_history failed: {e}\')\n\n    if errors:\n        print(\'V64.3 REGRESSION FAIL\'); [print(\' -\', e) for e in errors]; sys.exit(1)\n    print(\'V64.3 REGRESSION PASS — single response, safe filters, drill totals, per-FY quarters, data-quality wiring, KPI validation, scroll-reset, fishbone-backup restore, intensity drilldown.\')\n'

REGRESSION_V64_5_SOURCE = '"""Targeted V64.5 regression checks for the Admin/security/performance fixes.\n\nThis script uses a temporary SQLite database copied from the bundled seed and\nnever mutates the repository\'s quality.db. Run with:\n    python3 regression_v64_5.py\n"""\n\nimport gzip\nimport importlib\nimport os\nimport shutil\nimport sys\nimport tempfile\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent\nTMP = Path(tempfile.mkdtemp(prefix="qdash_v64_5_"))\nos.environ["DB_PATH"] = str(TMP / "quality.db")\nos.environ.pop("DATABASE_URL", None)\nos.environ["APP_VERSION"] = "V64.5"\nshutil.copy2(ROOT / "quality.db", TMP / "quality.db")\n\ntry:\n    sys.path.insert(0, str(ROOT))\n    server = importlib.import_module("server")\n    server._ensure_admin_schema()\n    server.ensure_fast_indexes()\n\n    conn = server.get_conn()\n    state0 = server._disposition_state(conn)\n    assert state0["revision"] == 0, state0\n    conn.close()\n\n    # Mutation revision must advance transactionally and be visible to a later\n    # preview-confirm comparison.\n    conn = server.get_conn()\n    before = server._disposition_state(conn)\n    server._mark_disposition_changed(conn)\n    conn.commit()\n    conn.close()\n    after = server._disposition_state()\n    assert after["revision"] == before["revision"] + 1, (before, after)\n    assert after["changed_at"], after\n\n    # Session activity flag must be honored by viewer authentication.\n    class Handler:\n        class Headers:\n            def get(self, name, default=""):\n                return "qdash_user=target-token" if name == "Cookie" else default\n        headers = Headers()\n\n    with server.SESSION_LOCK:\n        server.SESSIONS["target-token"] = {"role": "viewer", "active": True, "expires": server._dt.datetime.now().timestamp() + 600}\n    assert server._viewer_meta(Handler()) is not None\n    with server.SESSION_LOCK:\n        server.SESSIONS["target-token"]["active"] = False\n    assert server._viewer_meta(Handler()) is None\n\n    # User disable/reset now have one shared session-revocation primitive.\n    with server.SESSION_LOCK:\n        server.SESSIONS["a"] = {"user_id": 77, "role": "viewer", "active": True, "expires": server._dt.datetime.now().timestamp() + 600}\n        server.SESSIONS["b"] = {"user_id": 88, "role": "viewer", "active": True, "expires": server._dt.datetime.now().timestamp() + 600}\n    assert server._revoke_user_sessions(77) == 1\n    with server.SESSION_LOCK:\n        assert "a" not in server.SESSIONS and "b" in server.SESSIONS\n\n    # Backup listing: second unchanged read must be served from metadata cache,\n    # so gzip+JSON validation is not repeated.\n    server._write_backup_file("v64_5_regression")\n    server._backup_list_cache_clear()\n    calls = {"n": 0}\n    original = server._backup_is_valid\n    def counted(data, require_integrity=False):\n        calls["n"] += 1\n        return original(data, require_integrity=require_integrity)\n    server._backup_is_valid = counted\n    first = server._list_backups()\n    second = server._list_backups()\n    assert first and second, (first, second)\n    assert calls["n"] == len(first), (calls, len(first))\n    server._backup_is_valid = original\n\n    # Current bundled data remains readable and the optimized data-quality\n    # duplicate calculation has the expected zero-duplicate seed result.\n    conn = server.get_conn()\n    dup_groups = conn.execute("SELECT COUNT(*) FROM (SELECT UPPER(TRIM(batch_no)) b FROM disposition WHERE TRIM(COALESCE(batch_no,\'\'))<>\'\' GROUP BY UPPER(TRIM(batch_no)) HAVING COUNT(*)>1)").fetchone()[0]\n    total = conn.execute("SELECT COUNT(*) FROM disposition").fetchone()[0]\n    conn.close()\n    assert int(total) == 4936, total\n    assert int(dup_groups) == 0, dup_groups\n\n    print("V64.5 TARGETED REGRESSION PASS")\n    print(f"  disposition rows: {total}")\n    print(f"  mutation revision: {after[\'revision\']}")\n    print(f"  backup cache validation calls: {calls[\'n\']} for {len(first)} backup(s)")\nfinally:\n    try:\n        shutil.rmtree(TMP)\n    except Exception:\n        pass\n'

REGRESSION_V64_6_SOURCE = '"""Targeted V64.6 UI regression checks; does not modify the repository DB."""\nfrom pathlib import Path\nimport re\n\nROOT = Path(__file__).resolve().parent\napp_js = (ROOT / "app.js").read_text(encoding="utf-8")\napp_css = (ROOT / "app.css").read_text(encoding="utf-8")\nindex = (ROOT / "index.html").read_text(encoding="utf-8")\n\nassert \'const _tableNormalOrder = new Map()\' in app_js\nassert \'Three-state cycle for the same column: ascending → descending → natural order.\' in app_js\nassert \'rememberTableNormalOrder(tableId);\' in app_js, \'metric-table natural-order snapshot missing\'\nassert \'3rd click: reset to normal order\' in app_js\nassert \'_tableSortState.delete(tableId);\' in app_js\nassert \'aria-sort\' in app_js and \'ascending\' in app_js and \'descending\' in app_js and "\'none\'" in app_js\nassert \'function fmtDonutQty3\' in app_js\nassert \'function fmtDonutPct3\' in app_js\nassert \'fmtDonutPct3(s.frac)\' in app_js\nassert \'valFmt?opts.valFmt(s.val)\' in app_js\nassert \'data-tip="${escQcr(s.d[labelKey])}: ${(opts.valFmt?opts.valFmt(s.val):s.val.toFixed(2))} (${fmtDonutPct3(s.frac)})"\' in app_js\nassert \'.dashboard-table td:not(:first-child)\' in app_css\nassert re.search(r\'valFmt: fmtDonutQty3\', app_js)\n# Non-donut chart contracts must remain at their V64.5 precision.\nassert \'lineFmt: v => (v*100).toFixed(0)+"%"\' in app_js\nassert \'axisFmt: v => (v*100).toFixed(0)+"%"\' in app_js\nassert \'fmt: v => (v*100).toFixed(1)+"%"\' in app_js\nassert \'{key:"qty", label:"Qty (MT)", color:"#7C3AED", fmt: v => v.toFixed(1)}\' in app_js\nassert \'{key:"output_qty", label:"Output Qty (MT)", color:"#7C3AED", fmt: v => v.toFixed(0)}\' in app_js\nassert \'function fmtChartNum3\' not in app_js\nassert \'function fmtChartPct3\' not in app_js\nassert \'fmtChartPct3\' not in app_js\nassert \'.qcr-rca-table thead th{background:linear-gradient(180deg,#2f93cf 0%,#1f6690 100%);color:#fff\' in app_css\nassert \'html[data-theme="dark"] .qcr-rca-table thead th{background:linear-gradient(180deg,#2f93cf 0%,#194e6e 100%);color:#F0F7FF\' in app_css\nassert \'html[data-theme="dark"] .qcr-compare th{background:linear-gradient(180deg,#2f93cf 0%,#194e6e 100%)\' in app_css\nassert \'#tab-dashboard .panel > h3\' in app_css\nassert \'#tab-wcgrade .panel > h3\' in app_css\nassert \'#tab-defects .panel > h3\' in app_css\nassert \'#tab-weekly .panel > h3\' in app_css\nassert \'background:linear-gradient(135deg,#fbfdff 0%,#eef6ff 58%,#e5f0ff 100%) !important\' in app_css\nassert \'background:linear-gradient(135deg,#142541 0%,#173a63 62%,#194b78 100%) !important\' in app_css\nassert \'#tab-dashboard .panel > h3::before\' in app_css\nassert \'#tab-weekly .panel > h3::before\' in app_css\nassert \'Only dashboard analytics cards use this treatment\' in app_css\nassert \'<meta name="app-version" content="V64.6">\' in index\nassert re.search(r\'app\\.js\\?v=[\\w.]+\', index)\n\n# Main navigation must use the dashboard\'s blue-gradient treatment in both themes.\nassert \'.tabs > .tab-btn{\' in app_css\nassert \'background:linear-gradient(180deg,#4aa4d8 0%,#2b789f 100%) !important\' in app_css\nassert \'html[data-theme="dark"] .tabs > .tab-btn{\' in app_css\nassert \'background:linear-gradient(180deg,#2f93cf 0%,#194e6e 100%) !important\' in app_css\nassert \'html[data-theme="dark"] .tabs > .tab-btn.active\' in app_css\nassert re.search(r\'app\\.css\\?v=[\\w.]+\', index)\nassert re.search(r\'app\\.js\\?v=[\\w.]+\', index)\nassert \'id="digitalClock"\' in index\nassert \'function formatClockTime\' in app_js\nassert \'startDigitalClock();\' in app_js\nassert \'Current local date and time\' in index\nassert \'class="header-right-stack"\' in index\nassert \'class="digital-clock-icon"\' in index\nassert \'id="digitalClockDate"\' in index\nassert \'<div class="header-actions">\' in index\nassert index.index(\'class="digital-clock-block"\') < index.index(\'id="cmdkOpenBtn"\')\nassert \'digital-clock-date\' in app_css and \'.header-right-stack\' in app_css\nassert \'dateEl.textContent=\' in app_js\nassert \'h%12||12\' in app_js\nadmin_html=(ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'function formatClock12\' in (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'parseServerDateTime\' in (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'formatDateTime12(r.created_at,true)\' in (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'formatDateTime12(b.modified_at,true)\' in (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'timeAgo(raw)\' in (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'function formatDateTime12\' in (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'<meta name="app-version" content="V64.6">\' in (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'window.__adminRefreshLoaded?.();\' in (ROOT / \'admin.html\').read_text(encoding=\'utf-8\')\nassert \'formatClock12(d,withSeconds)\' in admin_html\nassert "months=[\'Jan\',\'Feb\',\'Mar\',\'Apr\',\'May\',\'Jun\',\'Jul\',\'Aug\',\'Sep\',\'Oct\',\'Nov\',\'Dec\']" in app_js\nassert \'formatDateTime12(b.modified_at,true)\' in admin_html\nassert \'qdash-presentation-drill-placeholder\' in app_js\nassert \'function elevateDrillModalForPresentation()\' in app_js\nassert \'function restoreDrillModalAfterPresentation()\' in app_js\nassert \'e.stopImmediatePropagation()\' in app_js\nassert \'⚖️ Quality Decision Mix — Qty (MT)\' in index\nassert "clone.querySelector(\'.analytics-expand-btn\')?.remove()" in app_js\n# Admin refresh must not be rebound to the legacy all-panels request storm.\n\nassert "Manual refresh is wired once by the canonical lazy-loader below." in admin_html\nassert "loadUsers();loadActivity();loadHome();loadDataQuality();loadImportHistory();loadKpiHistory();loadFishboneMaster();loadFishboneHistory();loadFishboneAlias();loadFishboneUnmapped();loadBackups();loadSecurityStatus()" not in admin_html\nassert "const touched=new Set([\'homePanel\',\'dataQualityPanel\',\'recordsPanel\',\'databasePanel\']);" in admin_html\nassert "window.__adminRecordState={...recState};" in admin_html\nprint(\'V64.6 UI REGRESSION PASS\')\n'

REGRESSION_PERIOD_COMPARISON_SOURCE = '"""Regression checks for quarter and financial-year period-over-period KPI comparison.\n\nUses an isolated temporary SQLite database and never touches production data.\n"""\nimport os\nimport sys\nimport tempfile\nfrom datetime import date\nfrom pathlib import Path\nROOT = Path(__file__).resolve().parent\n# The suite is stored in the repo root; keep imports local to the checkout and\n# avoid the old patch-workspace absolute path.\nsys.path[:0] = [str(ROOT)]\nwith tempfile.TemporaryDirectory(prefix=\'qdash_period_compare_\') as td:\n    os.environ.update(\n        DB_PATH=str(Path(td) / \'quality.db\'),\n        APP_VERSION=\'test-period-compare\',\n        ADMIN_USERNAME=\'admin\',\n        ADMIN_PASSWORD=\'Strong-Admin-1234!\',\n    )\n    os.environ.pop(\'DATABASE_URL\', None)\n    os.environ.pop(\'RENDER\', None)\n\n    import server\n    server._ensure_admin_schema()\n    server.ensure_fast_indexes()\n    conn = server.get_conn()\n    conn.execute(\'DELETE FROM disposition\')\n    conn.commit()\n    conn.close()\n\n    def rec(batch, d, decision, w):\n        m, wk, q, fy = server._derive_period_fields(d)\n        return {\n            \'heat_no\': \'H\' + batch,\n            \'batch_no\': batch,\n            \'work_center\': \'WC1\',\n            \'grade\': \'A\',\n            \'output_weight\': float(w),\n            \'main_defect\': \'NO DEFECT\' if decision == \'PRIME\' else \'STICKING\',\n            \'defect_intensity\': \'\' if decision == \'PRIME\' else \'LIGHT\',\n            \'quality_decision\': decision,\n            \'insp_lot_date\': d.isoformat(),\n            \'ud_date\': \'\',\n            \'month\': m,\n            \'week\': wk,\n            \'quarter\': q,\n            \'financial_year\': fy,\n        }\n\n    # FY 2025-26 Q4 (Jan-Mar 2026): 100 MT, 80 prime / 20 reject.\n    # FY 2026-27 Q1 (Apr-Jun 2026): 120 MT, 90 prime / 30 reject.\n    # FY 2026-27 Q2 (Jul-Sep 2026): 150 MT, 120 prime / 30 reject.\n    server._insert_records([\n        rec(\'Q4A\', date(2026, 2, 10), \'PRIME\', 80),\n        rec(\'Q4B\', date(2026, 2, 11), \'REJECT\', 20),\n        rec(\'Q1A\', date(2026, 5, 10), \'PRIME\', 90),\n        rec(\'Q1B\', date(2026, 5, 11), \'REJECT\', 30),\n        rec(\'Q2A\', date(2026, 8, 10), \'PRIME\', 120),\n        rec(\'Q2B\', date(2026, 8, 11), \'REJECT\', 30),\n    ])\n\n    base = {\n        \'month\': \'All\', \'week\': \'All\', \'quarter\': \'All\', \'financial_year\': \'All\',\n        \'work_center\': \'All\', \'grade\': \'All\', \'quality_decision\': \'All\', \'defect_intensity\': \'All\',\n    }\n    errors = []\n\n    # Quarter-only: latest Q2 resolves to FY 2026-27 and compares with Q1 in that FY.\n    q2 = dict(base, quarter=\'Q2\')\n    d = server.compute_kpis(q2)\n    if d[\'period\'].get(\'current\') != \'Q2 (FY 2026-27)\':\n        errors.append(f"Q2 current label: {d[\'period\']}")\n    if d[\'period\'].get(\'previous\') != \'Q1 (FY 2026-27)\':\n        errors.append(f"Q2 previous label: {d[\'period\']}")\n    fpy = next(k for k in d[\'kpis\'] if k[\'label\'] == \'First Pass Yield % (Prime%)\')\n    if abs(float(fpy.get(\'prev\') or 0) - 0.75) > 1e-12:\n        errors.append(f"Q2 previous FPY expected 0.75, got {fpy.get(\'prev\')}")\n\n    # Quarter-only Q1 rolls across the FY boundary to Q4 of the previous FY.\n    q1 = dict(base, quarter=\'Q1\')\n    d = server.compute_kpis(q1)\n    if d[\'period\'].get(\'current\') != \'Q1 (FY 2026-27)\':\n        errors.append(f"Q1 current label: {d[\'period\']}")\n    if d[\'period\'].get(\'previous\') != \'Q4 (FY 2025-26)\':\n        errors.append(f"Q1 previous label: {d[\'period\']}")\n    fpy = next(k for k in d[\'kpis\'] if k[\'label\'] == \'First Pass Yield % (Prime%)\')\n    if abs(float(fpy.get(\'prev\') or 0) - 0.80) > 1e-12:\n        errors.append(f"Q1 previous FPY expected 0.80, got {fpy.get(\'prev\')}")\n\n    # Financial Year: FY 2026-27 compares against FY 2025-26.\n    fy = dict(base, financial_year=\'FY 2026-27\')\n    d = server.compute_kpis(fy)\n    if d[\'period\'].get(\'previous\') != \'FY 2025-26\':\n        errors.append(f"FY previous label: {d[\'period\']}")\n    fpy = next(k for k in d[\'kpis\'] if k[\'label\'] == \'First Pass Yield % (Prime%)\')\n    # 210 prime / 270 total for FY26-27; 80 / 100 for FY25-26.\n    if abs(float(fpy.get(\'value\') or 0) - (210/270)) > 1e-12:\n        errors.append(f"FY current FPY expected 0.70, got {fpy.get(\'value\')}")\n    if abs(float(fpy.get(\'prev\') or 0) - 0.80) > 1e-12:\n        errors.append(f"FY previous FPY expected 0.80, got {fpy.get(\'prev\')}")\n\n    # Explicit Quarter + FY remains backward compatible.\n    explicit = dict(base, quarter=\'Q2\', financial_year=\'FY 2026-27\')\n    p = server.compute_prev_filters(explicit)\n    if p != dict(base, quarter=\'Q1\', financial_year=\'FY 2026-27\'):\n        errors.append(f"Explicit Q2+FY previous filters wrong: {p}")\n\n    # Invalid quarter labels must remain non-comparable rather than invent Q0/Q5 periods.\n    invalid = dict(base, quarter=\'Q5\', financial_year=\'FY 2026-27\')\n    if server.compute_prev_filters(invalid) is not None:\n        errors.append(\'Invalid Q5 quarter should have no previous-period comparison\')\n\n    if errors:\n        print(\'PERIOD COMPARISON REGRESSION FAIL\')\n        for e in errors:\n            print(\' -\', e)\n        raise SystemExit(1)\n    print(\'PERIOD COMPARISON REGRESSION PASS — Quarter (including FY-boundary Q1→Q4) and Financial Year KPI comparisons are active.\')\n'

SUITES = {
    'regression_smoke': 'Deep regression / smoke',
    'regression_test': 'Core non-destructive HTTP regression',
    'regression_v64_3': 'V64.3 regression',
    'regression_v64_5': 'V64.5 targeted regression',
    'regression_v64_6': 'V64.6 UI regression',
    'regression_period_comparison': 'Quarter + Financial Year period comparison regression',
}


def _run_suite(name: str, source: str) -> int:
    """Run one embedded suite from a temporary script in the repo root."""
    # The temp script intentionally lives beside server.py/app.js/etc. so every
    # suite's original ``Path(__file__).resolve().parent`` still points at repo root.
    fd, temp_name = tempfile.mkstemp(prefix=f'.{name}_', suffix='.py', dir=ROOT)
    os.close(fd)
    temp_path = Path(temp_name)
    try:
        temp_path.write_text(source, encoding='utf-8')
        print(f'\n=== {name} ===', flush=True)
        proc = subprocess.run([sys.executable, str(temp_path)], cwd=ROOT)
        return proc.returncode
    finally:
        try:
            temp_path.unlink()
        except FileNotFoundError:
            pass


def main() -> int:
    parser = argparse.ArgumentParser(description='Run the unified dashboard regression suite.')
    parser.add_argument('--list', action='store_true', help='List available suites and exit.')
    parser.add_argument('--suite', choices=list(SUITES), help='Run exactly one suite.')
    args = parser.parse_args()

    if args.list:
        for name, label in SUITES.items():
            print(f'{name}: {label}')
        return 0

    selected = [args.suite] if args.suite else list(SUITES)
    source_map = {
        'regression_smoke': REGRESSION_SMOKE_SOURCE,
        'regression_test': REGRESSION_TEST_SOURCE,
        'regression_v64_3': REGRESSION_V64_3_SOURCE,
        'regression_v64_5': REGRESSION_V64_5_SOURCE,
        'regression_v64_6': REGRESSION_V64_6_SOURCE,
        'regression_period_comparison': REGRESSION_PERIOD_COMPARISON_SOURCE,
    }

    failures = []
    for name in selected:
        rc = _run_suite(name, source_map[name])
        if rc != 0:
            failures.append((name, rc))

    if failures:
        print('\nUNIFIED REGRESSION FAIL', flush=True)
        for name, rc in failures:
            print(f' - {name}: exit {rc}', flush=True)
        return 1

    print(f'\nUNIFIED REGRESSION PASS — {len(selected)} suite(s) completed.', flush=True)
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
